        "runtime_revisions (id) ON DELETE RESTRICT, \n"
        "\tCONSTRAINT development_source_enablement_operation_state "
        "CHECK (state IN ('running', 'succeeded', 'failed', "
        "'reconciliation_required')), \n"
        "\tCONSTRAINT development_source_enablement_operation_phase "
