        "\tFOREIGN KEY(development_source_id) REFERENCES "
        "development_sources (id) ON DELETE RESTRICT, \n"
        "\tFOREIGN KEY(runtime_revision_id) REFERENCES "
        "runtime_revisions (id) ON DELETE RESTRICT, \n"
        "\tCONSTRAINT development_source_smoke_test_operation_state "
