        "\tcontainer_id VARCHAR(64) NOT NULL, \n"
        "\tbridge_id VARCHAR(36), \n"
        "\tbridge_port INTEGER NOT NULL, \n"
        "\tsecret_reference VARCHAR(36), \n"
        "\tidentity_json VARCHAR(4096), \n"
        "\tstate VARCHAR(16) NOT NULL, \n"
        "\tgeneration INTEGER NOT NULL, \n"
        "\tprepared_at VARCHAR(27) NOT NULL, \n"
        "\testablished_at VARCHAR(27), \n"
        "\tinvalidated_at VARCHAR(27), reviewed_installation BOOLEAN "
        "DEFAULT 0 NOT NULL, \n"
        "\tPRIMARY KEY (target_id), \n"
        "\tCONSTRAINT managed_bridge_trust_state CHECK (state IN "
        "('prepared','active','invalidated','revoked')), \n"
