        "\tdevelopment_source_id VARCHAR(36) NOT NULL, \n"
        "\tattached_at VARCHAR(32) NOT NULL, \n"
        "\tPRIMARY KEY (managed_instance_id, development_source_id), \n"
        "\tCONSTRAINT development_source_attachment_timestamp_bounded "
        "CHECK (length(attached_at) BETWEEN 20 AND 32), \n"
        "\tFOREIGN KEY(managed_instance_id) REFERENCES "
        "managed_instances (target_id) ON DELETE CASCADE, \n"
