        "\tCONSTRAINT mcp_remote_receipt_action_closed CHECK (action "
        "IN "
        "('up','down','left','right','select','back','home','context_"
        "menu','info','play_pause','stop','previous','next','volume_u"
        "p','volume_down','mute_toggle')), \n"
        "\tCONSTRAINT mcp_remote_receipt_state_closed CHECK (state IN "
