        "\tCONSTRAINT mcp_remote_receipt_terminal_consistent CHECK "
        "((state = 'pending' AND final_result IS NULL AND "
        "completed_at IS NULL AND screenshot_refresh_result IS NULL) "
        "OR (state IN ('completed','ambiguous') AND final_result IS "
        "NOT NULL AND completed_at IS NOT NULL AND "
        "screenshot_refresh_result IS NOT NULL)), \n"
        "\tCONSTRAINT mcp_remote_receipt_result_bounded CHECK "
        "(final_result IS NULL OR (length(final_result) BETWEEN 1 "
