        "(length(screenshot_capture_id) = 36 AND "
        "length(screenshot_captured_at) = 27)), \n"
        "\tCONSTRAINT uq_mcp_remote_receipt_client_request UNIQUE "
        "(client_id, request_id)\n"
        ")"
