        "\tcompleted_at VARCHAR(27), \n"
        "\ttarget_class VARCHAR(32) DEFAULT 'internal_lab' NOT NULL, \n"
        "\tbridge_id VARCHAR(36), \n"
        "\tbridge_request_id VARCHAR(36), \n"
        "\tbridge_receipt_id VARCHAR(36), \n"
        "\tfile_count INTEGER, \n"
        "\ttotal_bytes BIGINT, \n"
        "\tdeployment_mode VARCHAR(16) DEFAULT 'direct' NOT NULL, \n"
