        "\toriginal_runtime_state_revision INTEGER, \n"
        "\tfailure_phase VARCHAR(32), \n"
        "\tfailure_cause VARCHAR(64), \n"
        "\trecovery_state VARCHAR(32), \n"
        "\trecovery_digest VARCHAR(71), \n"
