        "\tCONSTRAINT mcp_workspace_deployment_initiator_closed CHECK "
        "((initiator_kind='mcp' AND client_id IS NOT NULL AND "
        "((deployment_mode='direct' AND repository_origin IS NULL) "
        "OR (deployment_mode='repository' AND repository_origin IS "
