        "deployment_mode='repository' AND repository_origin IS NOT "
        "NULL AND repository_origin='verified_existing' AND "
        "state='succeeded' AND phase='finalize' AND "
        "result_classification IS NOT NULL AND "
        "result_classification='repository_verified' AND "
        "mutation_started=0 AND target_stopped=0 AND sync_started=0 "
        "AND sync_completed=0 AND target_started=0)), \n"
        "\tCONSTRAINT mcp_workspace_deployment_inventory_closed CHECK "
        "(inventory_classification IN "
        "('not_checked','matched','failed','unknown')), \n"
        "\tCONSTRAINT mcp_workspace_deployment_markers_ordered CHECK "
        "((sync_started=0 OR mutation_started=1) AND "
        "(sync_completed=0 OR sync_started=1) AND (target_started=0 "
        "OR sync_completed=1)), \n"
        "\tCONSTRAINT mcp_workspace_deployment_mode_closed CHECK "
        "(deployment_mode IN ('direct','repository')), \n"
        "\tCONSTRAINT mcp_workspace_deployment_phase_closed CHECK "
        "(phase IN "
        "('claimed','preflight','stop','sync','transfer','replace','r"
        "eceipt','start','readiness','inventory','finalize','package'"
        ",'publication_approval','awaiting_kodi_update','verify_nativ"
        "e','verify_tree')), \n"
        "\tCONSTRAINT mcp_workspace_deployment_state_closed CHECK "
        "(state IN "
        "('pending','running','succeeded','failed','ambiguous','recon"
        "ciliation_required')), \n"
        "\tCONSTRAINT mcp_workspace_deployment_digests_valid CHECK "
        "((source_manifest_digest IS NULL OR "
        "(length(source_manifest_digest)=71 AND "
