        "event_kind='production_capability_screenshot_added') OR "
        "(operation='remove' AND "
        "event_kind='production_capability_screenshot_removed'))), \n"
        "\tCONSTRAINT production_capability_amendment_sets_bounded "
        "CHECK (length(before_configured_json) BETWEEN 2 AND 512 AND "
        "length(after_configured_json) BETWEEN 2 AND 512), \n"
        "\tCONSTRAINT production_capability_amendment_audit_bounded "
