        "\tFOREIGN KEY(target_id) REFERENCES targets (id) ON DELETE "
        "RESTRICT, \n"
        "\tCONSTRAINT uq_production_capability_amendment_revision "
        "UNIQUE (target_id, resulting_policy_revision)\n"
        ")"
