        "\tworkspace_id VARCHAR(36) NOT NULL, \n"
        "\tgeneration INTEGER NOT NULL, \n"
        "\taddon_id VARCHAR(128) NOT NULL, \n"
        "\taddon_version VARCHAR(64) NOT NULL, \n"
