        "zip_sha256 NOT GLOB '*[^0-9a-f]*'), \n"
        "\tCONSTRAINT reviewed_bridge_build_provenance_bounded CHECK "
        "(length(source_reference) BETWEEN 1 AND 512 AND "
        "length(reviewed_by) BETWEEN 1 AND 64 AND "
