        "(zip_sha256), \n"
        "\tCONSTRAINT reviewed_bridge_build_sets_bounded CHECK "
        "(capabilities_json IN "
        '(\'["screenshot"]\',\'["log_read","screenshot"]\',\'["screenshot"'
